```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The contract guarantees len(text) <= 100000, so the text is forwarded
        // to the session's channel as-is. The channel stamps its own session
        // identity on the confirmation; this node never fabricates it.
        let confirmation: DeliveryConfirmation = response_channel::send(&reply.text);

        // Ensures: delivered == true and present(session_id). A host that
        // refused the message or returned no session identity must not be
        // reported as a success, so trap rather than emit a false confirmation.
        if !confirmation.delivered || confirmation.session.is_empty() {
            panic!("response channel did not confirm delivery to a session");
        }

        confirmation
    }
}

export!(Node);
